package dynamicprogramming;
public class LevenshteinDistance { public static int distance(String a,String b){int[] prev=new int[b.length()+1],cur=new int[b.length()+1];for(int j=0;j<=b.length();j++)prev[j]=j;for(int i=1;i<=a.length();i++){cur[0]=i;for(int j=1;j<=b.length();j++)cur[j]=Math.min(Math.min(cur[j-1]+1,prev[j]+1),prev[j-1]+(Character.toLowerCase(a.charAt(i-1))==Character.toLowerCase(b.charAt(j-1))?0:1));int[] t=prev;prev=cur;cur=t;}return prev[b.length()];} }
